 static EvalContextR27 ctx(){ReplayDatasetR27 synthetic=ReplayDatasetR27.synthetic(5000,91,new int[0]);List<ReplayDatasetR27.Row> rows=new ArrayList<>();long start=com.ethk3.novaonepro.TargetIssueResolver.sequenceOrdinalSU1("202610240001");for(int i=0;i<synthetic.size();i++)rows.add(new ReplayDatasetR27.Row(com.ethk3.novaonepro.TargetIssueResolver.fromSequenceOrdinalSU1(start+i),start+i,synthetic.draws[i]));ReplayDatasetR27 d=ReplayDatasetR27.of(rows);return new EvalContextR27(new FeatureCacheR27(d),SplitR27.of(d,null),null);}
