 @Test public void distinctResearchViewsRetainTheirRealTargetAndMissingSources(){EvalContextR27 c=ctx();List<PolicySpecR27> ps=Arrays.asList(parent(),parent().withAst(PolicyAstR27.op("zscore",PolicyAstR27.leaf("cross",3,1)),null));for(String id:Arrays.asList("R01","R02","R03","R04","R07","R08","R12","R13","R15")){Map<String,Object> f=ResearchObservatoryR30R1.compute(id,c,ps,1);assertEquals(id,f.get("viewId"));assertEquals(id.equals("R08")?"TRAIN":"SELECT",f.get("role"));if(id.equals("R08")){assertEquals(c.data.ordinals[c.split.trainTo-1],f.get("throughOrdinal"));assertEquals(c.data.ordinals[Math.max(0,c.split.trainTo-BirthGateR27.PROBE)],f.get("fromOrdinal"));};assertNull(f.get("qualityEffective"));if(id.equals("R12")){assertEquals(1,((List<?>)f.get("matrixRows")).size());assertEquals(((List<?>)f.get("points")).size(),((List<?>)f.get("matrixColumns")).size());assertEquals(((Map<?,?>)((List<?>)f.get("points")).get(0)).get("label"),((List<?>)f.get("matrixColumns")).get(0));}assertTrue(id,((List<?>)f.get("points")).size()>0);assertTrue(((List<?>)f.get("points")).size()<=120);}Map<String,Object> missing=ResearchObservatoryR30R1.compute("R07",c,Collections.emptyList(),1);assertEquals("BLOCKED_DEPENDENCY",missing.get("status"));}
 @Test public void formalLabelPerturbationDoesNotChangeAnySelectAnalysis(){EvalContextR27 a=ctx();int[][] d=a.data.draws.clone();for(int t=a.split.selectTo;t<d.length;t++)d[t]=a.data.draws[0].clone();ReplayDatasetR27 changed=a.data.withDraws(d);EvalContextR27 b=new EvalContextR27(new FeatureCacheR27(changed),SplitR27.of(changed,null),null);for(String id:Arrays.asList("R04","R07","R08","R12","R13","R15")){Map<String,Object> x=ResearchObservatoryR30R1.compute(id,a,Collections.singletonList(parent()),1),y=ResearchObservatoryR30R1.compute(id,b,Collections.singletonList(parent()),1);assertEquals(id,JsonR27.write(x.get("points")),JsonR27.write(y.get("points")));}}
